CREATE OR REPLACE FORCE EDITIONABLE VIEW "PPPT"."PERSONALPUESTOESPECIALIDAD" ("IDESPECIALIDAD", "ESPECIALIDAD", "PESO", "IDPUESTO", "IDESCOLARIDAD", "IDPERSONAL") AS 
  SELECT CatEspecialidad.IdEspecialidad, CatEspecialidad.Especialidad, PuestoEspecialidad.Peso, PuestoEspecialidad.IdPuesto, PuestoEspecialidad.IdEscolaridad, Escolaridad.IdPersonal FROM Escolaridad INNER JOIN (PuestoEspecialidad INNER JOIN CatEspecialidad ON PuestoEspecialidad.IdEspecialidad = CatEspecialidad.IdEspecialidad) ON (Escolaridad.Especialidad = PuestoEspecialidad.IdEspecialidad) AND (Escolaridad.Grado = PuestoEspecialidad.IdEscolaridad);
